ON dbo.Users
    (Reputation)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);

DBCC SHOW_STATISTICS(N'dbo.Users', N'reppo') WITH STATS_STREAM;

UPDATE STATISTICS 
    dbo.Users 
    reppo 
WITH 
STATS_STREAM = 


