/*Naturale*/
SELECT
    u.*
FROM dbo.Users AS u
WHERE u.Reputation = 51
AND   1 = (SELECT 1);

/*
https://erikdarling.com/whats-the-point-of-1-select-1/
*/

/*First of all, ew*/
SELECT
    u.*
FROM dbo.Users AS u
WHERE u.Reputation = 23
AND   1 = (SELECT 1);

/*Synthesis*/
SELECT
    u.*
FROM dbo.Users AS u WITH (INDEX = reppo)
WHERE u.Reputation = 23
AND   1 = (SELECT 1);

/*
Sure, I get it! Don't SELECT * and all that jazz.

Even if you don't do that, *any* lookup will incur the same cost to the optimizer

Lookups have the same cost regardless of how many columns you're going back for
*/

SELECT
    u.*
FROM dbo.Users AS u WITH (INDEX = reppo)
WHERE u.Reputation = 51
AND   1 = (SELECT 1);

SELECT
    u.Id,
    u.AccountId
FROM dbo.Users AS u WITH (INDEX = reppo)
WHERE u.Reputation = 51
AND   1 = (SELECT 1);

/*
It's a stupid idea to have every nonclustered index include every column in the table
(Or account for every column you might select, maybe, someday.)

What's a clustered index?
 * Every column in the table logcially ordered by the clustered index key column(s)

What's a nonclustered index?
 * Every column in the includes ordered by the nonclustered index key column(s)

What's a nonclustered index that includes every column in the table?
 * Essentially a second clustered index

Dumb. Don't. Please.

*/


EXEC dbo.DropIndexes;

CREATE INDEX
    users
ON dbo.Users
    (CreationDate, Reputation, Id)
WITH
    (MAXDOP = 8, SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);
GO

CREATE INDEX
    posts
ON dbo.Posts
    (OwnerUserId, Score)
INCLUDE
    (PostTypeId)
WHERE
    (PostTypeId = 2)
WITH
    (MAXDOP = 8, SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);
GO

/*
Higher cost plans can be faster, but sometimes
won't be chosen because of the perceived "expense"
of random I/O by the optimizer, which stinks

Let's look at an example where the higher cost
plan added several beneficial operators to the plan
that speed things up a bit

*/


SELECT
    u.DisplayName,
    PostId = p.Id
FROM dbo.Users AS u
JOIN dbo.Posts AS p
  ON p.OwnerUserId = u.Id
WHERE  u.CreationDate > '20131210'
AND    u.Reputation > 100
AND    p.PostTypeId = 2
AND    p.Score > 1000
ORDER BY
    u.Id;

SELECT
    u.DisplayName,
    PostId = p.Id
FROM dbo.Users AS u WITH (INDEX = users) /*hint hint*/
JOIN dbo.Posts AS p
  ON p.OwnerUserId = u.Id
WHERE  u.CreationDate > '20131210'
AND    u.Reputation > 100
AND    p.PostTypeId = 2
AND    p.Score > 1000
ORDER BY
    u.Id;


/*
Compare query costs
Compare query speed

Was the optimizer right?
Did the cheaper plan win the race?

*/


