FROM dbo.Users AS u
JOIN dbo.Badges AS b
  ON b.UserId = u.Id
WHERE u.Reputation > 5000000;



/*
Cost percentage is relative.

*/


/*
Scanning the clustered index is really expensive!

*/
SELECT
    u.*
FROM
(
    SELECT
        u.*,
        n =
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    u.Id
                ORDER BY
                    u.Id
            )
    FROM dbo.Users AS u
) AS u
WHERE u.n = 0;

/*
Scanning the clustered index is free!

*/
SELECT
    u.*
FROM
(
    SELECT
        u.*,
        n =
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    u.AccountId
                ORDER BY
                    u.AccountId
            )
    FROM dbo.Users AS u
) AS u
WHERE u.n = 0
OPTION(MAXDOP 1);


/*
Cost *percentages* can be weird.

In the first query plan, scanning the clustered index is 96%
of the total query cost, because other operators had comparitively
low costs

In the second query plan, the Sort operator is given a high cost,
which makes scanning the clustered index look cheap contextually

While we're here, let's talk about operator times a little bit
 * In row mode only plans, operators times are cumulative from right to left
  * Parent operators include the times associated with child operators
 * In batch mode only plans, each operator tracks its own time individually
  * This isn't confusing at all but then
 * In mixed row AND batch mode plans, you'll see the same thing, just...
  * Row mode operators may seem to take a shocking amount of time

This is wall clock time, not CPU time. CPU time is available in operator properties.

Speaking of operator properties, you should always be looking at those.

There's good stuff in them.

*/

/*All row mode*/
SELECT
    u.*
FROM
(
    SELECT
        u.*,
        n =
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    u.AccountId
                ORDER BY
                    u.AccountId
            )
    FROM dbo.Users AS u
) AS u
WHERE u.n = 0
OPTION(MAXDOP 8);

/*Mostly batch mode*/
SELECT
    u.*
FROM
(
    SELECT
        u.*,
        n =
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    u.AccountId
                ORDER BY
                    u.AccountId
            )
    FROM dbo.Users AS u
) AS u
WHERE u.n = 0
OPTION(USE HINT('QUERY_OPTIMIZER_COMPATIBILITY_LEVEL_160'));


/*
While we're on the subject of query costing, let's
look at when a query does not have a high enough
cost for the optimizer to care about it at all.

*/

ALTER TABLE
    dbo.Users
ADD CONSTRAINT
    cu
CHECK
(
        Reputation > 0
    AND Reputation < 2000000
);

/*
A trivial plan!
*/
SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.Reputation < 0;

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.Reputation < 2;

/*
A fully optimized plan!

Which is slightly more expensive.

But much faster!

*/
SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.Reputation < 0
AND   1 = (SELECT 1);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.Reputation < 2
AND   1 = (SELECT 1);

ALTER TABLE
    dbo.Users
DROP CONSTRAINT
    cu;

/*
A trivial plan is the optimizer's way of
recognizing low cost queries, and not
expending a bunch of additional effort
coming up with plans for them.

There are no cost based decisions to make
in trivial plans, like which index to use,
or which operators to use to produce a result

*/

EXEC dbo.DropIndexes;

CREATE STATISTICS
    _WA_Sys_0000000A_08EA5793
ON dbo.Users
    (Reputation)
WITH STATS_STREAM = ;

/*Few rows?*/
SELECT DISTINCT TOP (4277 /*Sometimes 4304*/)
    u.Reputation /*But this will!*/
FROM dbo.Users AS u
OPTION(USE HINT('QUERY_OPTIMIZER_COMPATIBILITY_LEVEL_140'));

/*Some more rows?*/
SELECT DISTINCT TOP (4278)
    u.Reputation /*And this will!*/
FROM dbo.Users AS u
OPTION(USE HINT('QUERY_OPTIMIZER_COMPATIBILITY_LEVEL_140'));

/*Forcing a decision*/
SELECT DISTINCT TOP (5000)
    u.Reputation /*And this will!*/
FROM dbo.Users AS u
OPTION(ORDER GROUP, USE HINT('QUERY_OPTIMIZER_COMPATIBILITY_LEVEL_140'));


/*
Search 0 (OLTP): 
 * Basic decisions
 * Nested Loops vs Hash joins

Search 1:
 * Parallel plans
 * Transformations
 * Some join reordering

Search 2: 
 * The whole Enchilada™

When you write a query, some boring stuff happens
 * Check syntax validity
 * Check object reference existence

Then some cool stuff happens
 * Simplification
 * Cardinality Estimation/Join Ordering
 * Plan Exploration (Trivial, Full, etc.)

The optimizer will look at your query and
 * Discard unnecessary joins
 * Collapse duplicative expressions
 * Push predicates
 * Match Expressions (indexed views, computed columns, and filtered indexes)
 * Contradiction Detection (@i > 5 and @i < 5)

*/

SELECT
    oi.*
FROM sys.dm_exec_query_optimizer_info AS oi
ORDER BY
    oi.counter;


/*Unneccessary Join Discard*/
SELECT
    pt.*
FROM dbo.PostTypes AS pt
LEFT JOIN dbo.Posts AS p
  ON p.Id = pt.Id;

/*Expression Match*/
CREATE INDEX 
    u 
ON dbo.Users
    (Reputation) 
WHERE 
    Reputation >= 100000 
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.Reputation >= 1000000
AND   1 = (SELECT 1);


/*
Missing index requests are often junk.

Let’s start with some basics:
 * They really only care about the where clause
 * Joins always seem to end up in the INCLUDE list
 * Column suggestions are not in any particular order
  * Outside of being grouped into equality and inequality predicates
 * The impact is based on operator costs, which is often complete crap

Here's a good example

*/
EXEC dbo.DropIndexes;

SELECT TOP (3)
    u.DisplayName,
    TS = dbo.TotalScore(u.Id)
FROM dbo.Users AS u
WHERE u.Reputation > 100000
ORDER BY
    u.LastAccessDate DESC;

/*
UDF Inlining is blocked by a CTE in this case

*/
EXEC sp_helptext
    @objname = N'dbo.TotalScore';
/* 
https://learn.microsoft.com/en-us/sql/relational-databases/user-defined-functions/scalar-udf-inlining?view=sql-server-ver16#requirements 

*/


/*
When you see missing index requests in query plans, make sure:
 * The index would address a part of the plan
   that takes a significant amount of total execution time
 * The columns in the key and includes make sense
 * The column order in the key make sense (Include list isn't the entire table)
 * You don't already have an index that can be altered
   to suit the request, rather than creating a whole new index
 * You don't already have like 30 indexes on the table

Other things that can benefit from index key ordering are ignored
 * Joins
 * Order By
 * Group By
 * Windowing function Partition By/Order By

Eager Index Spools are another form of missing index request (usually):
 * SQL Server creates an index on the fly for you 🤔
 * Sometimes it does this even when you have a suitable index 🤔
 * Doesn't throw a missing index request 🤔
 * Discards index when the query finishes 🤔
 * Still doesn't tell you about it 🤔
 * Will do this every time the query runs 🤔

*/


/*
Things to pay attention to in query plans (redux):
 * Operator times
 * Wait stats (or use sys.dm_exec_session_wait_stats)
 * Estimateds vs Actuals
 * Spills
 * Parallel thread distribution

We've looked at operator times quite a bit, so
let's look at other things that can be useful


*/






/*
When wait stats in query plans can be useful...

*/
DBCC DROPCLEANBUFFERS;
GO
SELECT c = COUNT_BIG(*) FROM dbo.Posts AS p WHERE p.Score = -166 AND 1 = (SELECT 1);
GO
SELECT c = COUNT_BIG(*) FROM dbo.Posts AS p WHERE p.Score = -166 AND 1 = (SELECT 1);
GO

/*
Spills
Estimates/Actuals

*/
DECLARE
    @Top bigint = 100 * 358,
    @Dummy integer;

SELECT DISTINCT TOP (@Top)
    @Dummy = V.PostId
FROM dbo.Votes AS V
OPTION (OPTIMIZE FOR (@Top = 1));


/*
When wait stats aren't useful
Parallel thread distribution

*/
CREATE INDEX
    pq
ON dbo.Posts
(
    CreationDate,
    ClosedDate,
    AcceptedAnswerId
)
INCLUDE
    (Score)
WHERE
    (Score > 0)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);
GO


/*Put these in a new window*/
SELECT
    pbs.*
FROM dbo.parallel_but_serial AS pbs
ORDER BY
    pbs.flat_date;


SELECT
    ws.session_id,
    ws.wait_type,
    ws.waiting_tasks_count,
    ws.wait_time_ms,
    avg_ms_per_wait =
        ISNULL
        (
           CONVERT
           (
               decimal(38, 2),
               ws.wait_time_ms /
               NULLIF
               (
                   1.* ws.waiting_tasks_count,
                   0.
               )
           ),
           0.
        ),
    ws.max_wait_time_ms,
    ws.signal_wait_time_ms
FROM sys.dm_exec_session_wait_stats AS ws
WHERE ws.session_id = @@SPID
AND   ws.wait_time_ms > 0
ORDER BY
    ws.wait_time_ms DESC;


