/*
We've seen lot of cases where the optimizer has
gotten costing and estimation wrong for various
reasons, and we've gotten weird plans, bad plans,
and missing index requests that would not change
anything meaningfully.

Let's look at some examples of things you can do
that will screw up cardinality estimation, and
how some database "stuff" can make one cardinality
estimate good and another cardinality estimate bad.

*/

EXEC dbo.DropIndexes;

/*
This section is included for the inquisitive reader, for completeness.
SARGability is an important concept, and can not only mess with costing,
but can also prevent more appropriate plan choices by the optimizer. They
can also mess with cardinality estimation, which messes with costing.

I'm not going to go through all these, because we have other things to discuss.


First lesson:

Anything you do that makes your job easier
will inevitable make SQL Server's job harder

When you write a join or where clause, it's your job
to make that task as easy as possible on SQL Server

Which sometimes makes things harder on you.


 * function(column) = something

 This goes for both built-in and user-defined functions
  * ISNULL, COALESCE, LEFT, RIGHT, L/R/TRIM, SUBSTRING, REPLACE, etc.

 These are *presentation layer* functions with zero relational meaning

 You should use these when you *show* people data, not for when you need to *find* data

 You can still scan indexes when these functions are used, but the
 part of the query engine (expression service) that's responsible for
 executing these functions is far removed from the storage engine

*/

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE SUBSTRING(u.DisplayName, 1, 1) = N'z';


SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.DisplayName LIKE N'z%';


SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE COALESCE(u.CreationDate, '19000101') >= '20130101'
AND   1 = (SELECT 1);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.CreationDate >= '20130101'
AND   1 = (SELECT 1);


/*
 /*--------------------------*/
 * column + column = something
 * column + value  = something
 * value  + column = something

 These are all signs that you're not storing data correctly

 Store data the way you query it, and query data the way you store it
  * Do a better job of cleaning data on the way in
  * Create computed columns to store data the way you search it

*/

CREATE INDEX
    u
ON dbo.Users
    (UpVotes, DownVotes)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.UpVotes + u.DownVotes > 500
AND   1 = (SELECT 1);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.UpVotes + u.DownVotes > 5000
AND   1 = (SELECT 1);

SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.UpVotes + u.DownVotes > 50000
AND   1 = (SELECT 1);

/*Just add this first and run through again*/
ALTER TABLE
    dbo.Users
ADD
    UpDown
AS
    CONVERT(integer, (UpVotes + DownVotes));

/*Now add this*/
CREATE INDEX
    u2
ON dbo.Users
    (UpDown)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);

EXEC dbo.DropIndexes;
ALTER TABLE dbo.Users DROP COLUMN UpDown;
ALTER TABLE dbo.Users REBUILD;


/*
 * column = @something or @something IS NULL

 The catch-all query pattern that will sink performance every time

 It doesn't matter how you choose to get cute about this, either
  * column = ISNULL(@parameter, column)
  * column = COALESCE(@parameter, column)
  * column = CASE WHEN @parameter IS NOT NULL THEN @parameter ELSE column END

 It all ends up poorly.

 Easy way out:
  * OPTION(RECOMPILE)

 Harder way out:
  * Parameterized dynamic SQL

*/

CREATE INDEX
    p
ON dbo.Posts
    (ParentId)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);
GO

CREATE OR ALTER PROCEDURE
    #p
(
    @ParentId integer
)
AS
BEGIN
SET NOCOUNT ON;

    SELECT
        c = COUNT_BIG(*)
    FROM dbo.Posts AS p
    WHERE (p.ParentId = @ParentId OR @ParentId IS NULL);

    SELECT
        c = COUNT_BIG(*)
    FROM dbo.Posts AS p
    WHERE (p.ParentId = @ParentId OR @ParentId IS NULL)
    OPTION(RECOMPILE);

    DECLARE
        @s nvarchar(MAX) = N'';

    SELECT
        @s += N'
    SELECT
        c = COUNT_BIG(*)
    FROM dbo.Posts AS p
    WHERE 1 = 1       
';
    IF @ParentId IS NOT NULL
    BEGIN
        SELECT
            @s += N'
    AND   p.ParentId = @ParentId
            ';
    END

    EXEC sys.sp_executesql
        @s,
      N'@ParentId integer',
        @ParentId;
END;
GO

EXEC #p
    @ParentId = 184618;

GO
/*
 * column like '%something'

 Leading wild cards are rough.

 Sometimes you can make a computed column with the REVERSE function,
 index it, and then do your searches against that instead.

 Most of the time, you just have to suck it up. Strings were a mistake.

*/


SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.DisplayName LIKE N'%Skeet';


ALTER TABLE
    dbo.Users
ADD
    DisplayNameReversed
AS
    CONVERT(nvarchar(40), REVERSE(DisplayName));

CREATE INDEX
    u
ON dbo.Users
    (DisplayNameReversed)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);


SELECT
    c = COUNT_BIG(*)
FROM dbo.Users AS u
WHERE u.DisplayNameReversed LIKE REVERSE(N'%Skeet');


/*
 * column = case when …
 * value  = case when column …

 You know what else is a CASE expression internally?
 * COALESCE
 * IIF
 * CHOOSE

 Guess what they both have in common?
 They're not good ideas in join or where clauses

https://erikdarling.com/why-case-expressions-are-bad-in-the-where-clause/

*/



/*

 * Mismatching data types

 More commonly known as implicit conversions.

 Many of them will produce scans and cardinality mis-estimates.

 Usually the biggest offenders (aside from bad database design)
 are ORMs where developers don't strongly type parameters for type and length,
 and a bunch of parameters get sent in as nvarchar that really shouldn't be

https://erikdarling.com/implicit-conversion-is-a-sargability-problem/

https://erikdarling.com/sargability-week-why-implicit-conversions-arent-sargable/
*/


EXEC dbo.DropIndexes;

/*
This is where we come back to costing!


Of course, one of the most difficult tasks for a
query optimizer that needs to work well generally
is parameter sniffing.

The optimizer can usually come up with a good plan
for one set of parameters, but if data is skewed
or someone sends in a real weird combination of them,
all costing goes immediately out the window.

Plans that can be good for dealing with small amounts
of data can be awful for dealing with large amounts.

*/
EXEC dbo.DropIndexes;

CREATE INDEX
    v
ON dbo.Votes
    (VoteTypeId)
WITH
    (SORT_IN_TEMPDB = ON, DATA_COMPRESSION = PAGE);

SELECT
    vt.Name,
    v.VoteTypeId,
    c = FORMAT(COUNT_BIG(*), 'N0')
FROM dbo.Votes AS v
JOIN dbo.VoteTypes AS vt
  ON v.VoteTypeId = vt.Id
--WHERE vt.Id IN (1, 2, 7)
GROUP BY
    vt.Name,
    v.VoteTypeId
ORDER BY
    COUNT_BIG(*) DESC;

DBCC FREEPROCCACHE;

ALTER DATABASE
    StackOverflow2013
SET
    COMPATIBILITY_LEVEL = 160;

SELECT
    dsc.name,
    dsc.value,
    dsc.is_value_default
FROM sys.database_scoped_configurations AS dsc
WHERE dsc.name = N'PARAMETER_SENSITIVE_PLAN_OPTIMIZATION';



DECLARE
    @VoteTypeId integer,
    @s nvarchar(MAX) = N'';

SELECT
    @VoteTypeId = 1, /*Flip this between 7 and 1, show saved plan for 2*/
    @s = N'
SELECT TOP (10)
    v.PostId,
    c = COUNT_BIG(*)
FROM dbo.Votes AS v
WHERE v.VoteTypeId = @VoteTypeId
GROUP BY
    v.PostId
ORDER BY
    c DESC;';

EXEC sys.sp_executesql
    @s,
  N'@VoteTypeId integer',
    @VoteTypeId;